```go
package main

import (
    "fmt"
    "unicode/utf8"
)

func main() {
    text := "café"
    fmt.Println(len(text))
    fmt.Println(utf8.RuneCountInString(text))
    for index, value := range text {
        fmt.Printf("%d:%U ", index, value)
    }
    fmt.Println()
}
```
The first two lines are `5` and `4`. Range indexes are byte offsets for the start of each decoded rune.

```go
package main

import (
    "fmt"
    "unicode/utf8"
)

func main() {
    text := string([]byte{'A', 0xff, 'B'})
    fmt.Println(utf8.ValidString(text), len(text))
    for index, value := range text {
        fmt.Printf("%d:%U ", index, value)
    }
    fmt.Println()
}
```
Validation is false. Range still yields `A`, U+FFFD, and `B`, advancing one byte over the invalid value.
